def uninstall_package(root_path: str, package_spec: str, binaries_to_remove: List[str], context: dict) -> dict:
    import json
    import os
    import shutil
    from typing import List

    tracking_file = os.path.join(root_path, "install_tracking.json")
    if not os.path.exists(tracking_file):
        return {"success": False, "error": "tracking file not found"}

    with open(tracking_file, "r", encoding="utf-8") as f:
        data = json.load(f)

    packages = data.get("packages", [])
    binaries = data.get("binaries", [])
    installation_root = data.get("installation_root", root_path)

    # identify package by spec (match id or name)
    matched = [p for p in packages if package_spec == p.get("id") or package_spec == p.get("name")]
    if not matched:
        return {"success": False, "error": "package not found"}

    pkg = matched[0]
    pkg_id = pkg.get("id")

    # Uninstall package files if present
    pkg_path = os.path.join(installation_root, pkg_id)
    if os.path.isdir(pkg_path):
        try:
            shutil.rmtree(pkg_path)
        except Exception as e:
            return {"success": False, "error": f"failed to remove package directory: {e}"}

    # Uninstall specified binaries
    removed_binaries = []
    for bname in binaries_to_remove:
        bin_entries = [b for b in binaries if b.get("name") == bname and b.get("package_id") == pkg_id]
        for be in bin_entries:
            bin_path = be.get("path")
            if not bin_path:
                bin_path = os.path.join(installation_root, "bin", bname)
            if bin_path and os.path.exists(bin_path):
                try:
                    os.remove(bin_path)
                except Exception as e:
                    return {"success": False, "error": f"failed to remove binary {bname}: {e}"}
            removed_binaries.append(bname)

    # Update tracking: remove package and related binaries
    data["packages"] = [p for p in packages if p.get("id") != pkg_id]
    data["binaries"] = [b for b in binaries if b.get("package_id") != pkg_id]

    with open(tracking_file, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)

    return {"success": True, "package_id": pkg_id, "uninstalled_binaries": removed_binaries}

